CREATE TYPE "ProxyProtocol" AS ENUM ('HTTP','HTTPS','SOCKS4','SOCKS5');
CREATE TYPE "ProxyStatus" AS ENUM ('NEW','TESTING','ACTIVE','FAILED','COOLDOWN');
CREATE TYPE "MaintenanceStatus" AS ENUM ('RUNNING','COMPLETED','FAILED');
CREATE TYPE "JobStatus" AS ENUM ('PENDING','RUNNING','COMPLETED','FAILED');
CREATE TABLE "Proxy" ("id" TEXT PRIMARY KEY,"ip" TEXT NOT NULL,"port" INTEGER NOT NULL,"protocol" "ProxyProtocol" NOT NULL,"country" TEXT,"countryCode" TEXT,"city" TEXT,"isp" TEXT,"anonymity" TEXT,"source" TEXT NOT NULL,"status" "ProxyStatus" NOT NULL DEFAULT 'NEW',"latencyMs" INTEGER,"sourceLatencyMs" INTEGER,"sourceUptime" DOUBLE PRECISION,"sourceLastCheckedAt" TIMESTAMP(3),"firstSeenAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"lastSeenAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"lastCheckedAt" TIMESTAMP(3),"lastSuccessfulCheckAt" TIMESTAMP(3),"cooldownUntil" TIMESTAMP(3),"consecutiveFailures" INTEGER NOT NULL DEFAULT 0,"successfulChecks" INTEGER NOT NULL DEFAULT 0,"failedChecks" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "Proxy_protocol_ip_port_key" ON "Proxy"("protocol","ip","port");
CREATE INDEX "Proxy_status_idx" ON "Proxy"("status"); CREATE INDEX "Proxy_protocol_idx" ON "Proxy"("protocol"); CREATE INDEX "Proxy_countryCode_idx" ON "Proxy"("countryCode"); CREATE INDEX "Proxy_cooldownUntil_idx" ON "Proxy"("cooldownUntil");
CREATE TABLE "ProxyCheck" ("id" TEXT PRIMARY KEY,"proxyId" TEXT NOT NULL,"success" BOOLEAN NOT NULL,"latencyMs" INTEGER,"errorType" TEXT,"checkedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ProxyCheck_proxyId_fkey" FOREIGN KEY ("proxyId") REFERENCES "Proxy"("id") ON DELETE CASCADE);
CREATE INDEX "ProxyCheck_proxyId_checkedAt_idx" ON "ProxyCheck"("proxyId","checkedAt");
CREATE TABLE "ProxyMaintenanceRun" ("id" TEXT PRIMARY KEY,"startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"finishedAt" TIMESTAMP(3),"initialActiveCount" INTEGER NOT NULL,"retestedCount" INTEGER NOT NULL DEFAULT 0,"survivedCount" INTEGER NOT NULL DEFAULT 0,"failedCount" INTEGER NOT NULL DEFAULT 0,"newCandidatesTested" INTEGER NOT NULL DEFAULT 0,"newProxiesAdded" INTEGER NOT NULL DEFAULT 0,"finalActiveCount" INTEGER NOT NULL DEFAULT 0,"status" "MaintenanceStatus" NOT NULL DEFAULT 'RUNNING',"errorMessage" TEXT);
CREATE TABLE "MaintenanceJob" ("id" TEXT PRIMARY KEY,"status" "JobStatus" NOT NULL DEFAULT 'PENDING',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"startedAt" TIMESTAMP(3),"finishedAt" TIMESTAMP(3),"error" TEXT);
CREATE INDEX "MaintenanceJob_status_createdAt_idx" ON "MaintenanceJob"("status","createdAt");
